import java.util.*;

public class Main {
    static final int N = 2000005;
    static int tot, S, T, n, m, k, c, d;
    static int[] ne = new int[N], fi = new int[N], zz = new int[N], sl = new int[N], dis = new int[N], flag = new int[N], w = new int[N], cur = new int[N], x = new int[N], y = new int[N];
    static Queue<Integer> Q = new LinkedList<>();

    static void addEdge(int x, int y, int z, int v) {
        ne[++tot] = fi[x];
        fi[x] = tot;
        zz[tot] = y;
        sl[tot] = z;
        w[tot] = v;
        ne[++tot] = fi[y];
        fi[y] = tot;
        zz[tot] = x;
        sl[tot] = 0;
        w[tot] = -v;
    }

    static boolean bfs() {
        Q.clear();
        Arrays.fill(dis, 0x3f);
        dis[S] = 0;
        Q.offer(S);
        while (!Q.isEmpty()) {
            int now = Q.poll();
            flag[now] = 0;
            for (int i = fi[now]; i != 0; i = ne[i]) {
                if (sl[i] > 0 && dis[zz[i]] > dis[now] + w[i]) {
                    dis[zz[i]] = dis[now] + w[i];
                    if (flag[zz[i]] == 0) {
                        flag[zz[i]] = 1;
                        Q.offer(zz[i]);
                    }
                }
            }
        }
        return dis[T] <= 1000000000;
    }

    static int dfs(int x, int y) {
        int s = 0, b;
        flag[x] = 1;
        if (x == T) return y;
        for (int i = cur[x]; i != 0; i = ne[i]) {
            if (flag[zz[i]] == 0 && sl[i] > 0 && dis[zz[i]] == dis[x] + w[i] && (b = Math.min(y, dfs(zz[i], Math.min(y, sl[i])))) > 0) {
                sl[i] -= b;
                sl[i ^ 1] += b;
                s += b;
                y -= b;
                if (y == 0) return s;
            }
        }
        return s;
    }

    static int gao() {
        int flow = 0;
        while (bfs()) {
            System.arraycopy(fi, 0, cur, 0, fi.length);
            int f;
            while ((f = dfs(S, Integer.MAX_VALUE)) > 0) {
                flow += f;
            }
        }
        return flow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        S = 0;
        T = 1;
        tot = 1;

        for (int i = 1; i <= k; i++) {
            int xVal = sc.nextInt();
            addEdge(S, xVal + 1, 1, 0);
        }

        for (int i = 1; i <= m; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }

        for (int i = 0; i <= n + k; i++) {
            addEdge(2 + i * n, T, k, 0);
            if (i == n + k) break;
            for (int j = 1; j <= m; j++) {
                for (int l = k; l >= 0; l--) {
                    int fromX = x[j] + 1 + i * n;
                    int fromY = y[j] + 1 + i * n;
                    int toX = y[j] + 1 + i * n + n;
                    int toY = x[j] + 1 + i * n + n;
                    int cost = (l * 2 + 1) * d + c;
                    addEdge(fromX, toX, 1, cost);
                    addEdge(fromY, toY, 1, cost);
                }
            }
            for (int j = 1; j <= n; j++) {
                int from = j + 1 + i * n;
                int to = from + n;
                addEdge(from, to, k, c);
            }
        }

        System.out.println(gao());
        sc.close();
    }
}
